def check(p,gin):
    go=G[f'Demo pair {p} output']
    Hh,Ww=len(gin),len(gin[0])
    bgc=Counter(x for row in gin for x in row).most_common(1)[0][0]
    cs=comps_of(gin,bgc)
    groups=defaultdict(list)
    for comp in cs:
        col=gin[next(iter(comp))[0]][next(iter(comp))[1]]
        groups[col].append(sorted(comp))
    out=[row[:] for row in gin]
    for col,comps in groups.items():
        # template = largest comp of this color
        t=max(comps,key=len)
        cr,cy,tset=t
        for r,c in t:
            tc=gin[r][c]
        anchor_cells=[]
        for c2 in comps:
            if len(c2)==1:
                ar,ac=next(iter(c2)); anchor_cells.append((ar,ac))
        trr,trc=min(rr for rr,cc in t),max(rr for rr,cc in t)
        trc2=min(cc for rr,cc in t),max(cc for rr,cc in t)
        for ar,ac in anchor_cells:
            for rr,cc in t:
                nr,nc=ar+(rr-trr)//2,ac+(cc-trc2)//2
                if out[nr][nc]==bgc:
                    out[nr][nc]=tc
    return out==go
